<dialog id="mobile-menu-drawer" tabindex="-1" autofocus class="mobile-menu-drawer" aria-labelledby="mobile-menu-title"><div class="mobile-menu-inner"><h2 id="mobile-menu-title" class="sr-only"><?=e(t('Header menu'))?></h2><nav class="drawer-menu-links" aria-label="<?=e(t('Header menu'))?>"><?php renderMobileMenu();?></nav></div></dialog>
<button type="button" class="mobile-panel-backdrop" aria-label="<?=e(t('Close'))?>" hidden></button><dialog id="search-drawer" tabindex="-1" autofocus class="search-drawer" aria-labelledby="search-heading"><div class="search-drawer-inner"><h2 id="search-heading" class="sr-only"><?=e(t('Search'))?></h2><form action="/" class="drawer-search-form" data-search-form><label class="sr-only" for="drawer-query"><?=e(t('Search posts'))?></label><input id="drawer-query" name="q" placeholder="<?=e(t('Search posts…'))?>" value="<?=e($_GET['q'] ?? '')?>" autocomplete="off"><button class="button" aria-label="<?=e(t('Submit search'))?>"><?=icon('search')?></button></form><div class="search-section-heading"><h3><?=e(t('Recent searches'))?></h3><button class="text-button" id="clear-search-history"><?=e(t('Clear'))?></button></div><div data-search-history></div><h3 class="search-section-heading"><?=e(t('Categories'))?></h3><div class="search-chips"><?php foreach ($categories as $c): ?><a href="/?category=<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach; ?></div></div></dialog><dialog id="category-dialog"><form id="category-form"><div class="dialog-heading"><h2><?=e(t('Create category'))?></h2><button type="button" class="icon-button" id="close-dialog" aria-label="<?=e(t('Close'))?>"><?=icon('close')?></button></div><label for="category-name"><?=e(t('Category name'))?></label><input id="category-name" name="name" maxlength="40" placeholder="e.g. Notes" required><label for="new-category-parent"><?=e(t('Parent category'))?></label><select id="new-category-parent" name="parent_id"><option value="0"><?=e(t('Top level'))?></option><?php foreach($categories as $rootCategory):if($rootCategory['parent_id']!==null)continue;?><option value="<?=$rootCategory['id']?>"><?=e($rootCategory['name'])?></option><?php endforeach;?></select><p id="category-error" role="status"></p><button class="button" type="submit"><?=e(t('Create category'))?></button></form></dialog><div class="toast" id="toast" role="status" hidden></div>